INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_07fbde5c5c3f28cd86301896', 'zh-CN', 'CloseFlight 签证指南', '输入护照、居住地和目的地，快速查询签证要求、停留时长、护照有效期规则及官方申请链接，并可邮件获取材料清单 PDF。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_07fbde5c5c3f28cd86301896', 'en', 'CloseFlight Visa Guide', 'Check free in seconds whether your passport needs a visa for any destination: visa or not, how long you can stay, the passport validity rule and the official apply link. Need more?', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3c7a594cc3e5803fde966448', 'zh-CN', 'Battle Trails：战场遗迹路线社区', '发现与分享战场、战壕、地堡等历史遗迹路线的社区，路线包含站点、照片与亲历者记述。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3c7a594cc3e5803fde966448', 'en', 'Battle Trails', 'Battle Trails is a community for discovering and sharing routes through battlefields, trenches, bunkers and other places where history left its mark on the terrain.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_37612a35785a87c66382c835', 'zh-CN', 'SkyReview：航班评价', '按航线查看真实乘客评价，了解航班准点、机型与空乘情况，落地后快速打分晒图点评。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_37612a35785a87c66382c835', 'en', 'SkyReview – Flight Reviews', 'Know what a flight is really like before you book it. See real passenger reviews by route: which flights are always late, which planes are old and cramped, which crews are great, and which airlines hit you with surprise fees.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_2de32eaf2b1bce94d44570c8', 'zh-CN', 'Trauddy：日本旅行行李空间共享', '在日本旅行时利用行李空余空间赚钱，或找顺路旅行者代带物品，支付由平台托管至双方确认。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_2de32eaf2b1bce94d44570c8', 'en', 'Trauddy', 'Earn from the spare space in your luggage on trips around Japan, or find a traveller heading your way to bring what you need. Payments are held safely until both sides confirm.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3ce416d8c81e675a4a16e1fe', 'zh-CN', 'LoungeReview：机场休息室准入查询', '根据行程、常旅客等级、会员和信用卡精准判断可用的机场休息室，覆盖3800+休息室并支持购买通行证。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3ce416d8c81e675a4a16e1fe', 'en', 'LoungeReview', 'The ONLY app that tells you exactly which airport lounges you can access, based on your itinerary, frequent flyer status, lounge memberships and credit cards. No access? Buy a pass in a few taps.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3e97850de89099233a7be0ac', 'zh-CN', 'GoVayo：印度精选团体旅行与本地体验预订', '在印度发现并预订精选团体旅行、周末度假和地道本地体验。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_3e97850de89099233a7be0ac', 'en', 'GoVayo', 'Discover and book curated group trips, weekend getaways, and authentic local experiences across India with GoVayo.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_54f48dcfda66f14f090833a9', 'zh-CN', 'Slowmap：旅行规划器', '输入目的地，Slowmap 会按住宿、交通方式、旅行节奏和目的生成逐日行程，并提供预算、天气预报、美食推荐和行程文档存储。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_54f48dcfda66f14f090833a9', 'en', 'Slowmap: Travel Planner', 'You tell where you''re going. Slowmap plans the whole trip for you. You get a day-by-day itinerary built around what really shapes a trip: where you''re staying each night, whether you''re driving or taking the train, the pace you like and wh…', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_4a31ba013b4f13f97c6702bd', 'zh-CN', 'Sorted Trip 个性化旅行推荐', '输入目的地、同行人和偏好，获取个性化行程建议。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_4a31ba013b4f13f97c6702bd', 'en', 'Sorted Trip', 'Tell us where you''re going, who you''re with and what you want. We''ll tell you what we''d do.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_6ea2f4033afc3776de071762', 'zh-CN', 'iZhinga - 你的智能旅行伴侣应用', '以旅行者为中心的智能旅行伴侣，结合实时城市信息与人工核实的本地建议，帮助旅客在旅途中做出更好决策。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_6ea2f4033afc3776de071762', 'en', 'iZhinga - Your Si Travel Companion App', 'iZhinga is an SI-powered travel companion built around the traveller, not transactions. Combining contextual SI, real-time city intelligence and human-verified local insights, it helps travellers make better decisions throughout their jour…', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_87df76efa4516d9818c5d44c', 'zh-CN', 'Thikana', 'Thikana 帮助旅行者按预算和位置发现实惠酒店与民宿，并让小型房东通过 WhatsApp 直接联系住客。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_87df76efa4516d9818c5d44c', 'en', 'Thikana', 'Thikana helps travellers discover affordable hotels and homestays while helping small property owners improve their online visibility.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_28026da02899a23498054beb', 'zh-CN', 'diff-tour：把 git diff 变成逐步导览', '把 git diff 转成可逐步浏览的导览，用提问引导你像资深工程师一样理解代码改动。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_28026da02899a23498054beb', 'en', 'diff-tour', 'Now that AI writes the code, what should engineers learn? Understanding code still matters, and understanding code means learning how a senior engineer thinks.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_97e91d65bbc4a6929c0109ef', 'zh-CN', 'Impakto Navigator 智能运动鞋', '印度品牌 Impakto 的智能运动鞋，内置传感器与蓝牙，可计步、测距、算卡路里，支持脚跟脚尖手势切歌、接听电话、拍照，并有 SOS、跌倒检测与 GPS 运动记录。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_97e91d65bbc4a6929c0109ef', 'en', 'Impakto Navigator Hardcore Smart Shoes', 'Impakto Navigator are smart shoes with built-in sensors and Bluetooth, made by Indian athleisure brand Impakto.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_97fc301222e46ab510c3380c', 'zh-CN', 'Atlas Bird 环球飞行', '操控小鸟穿越障碍，游历伊朗、土耳其、北欧到加拿大等地的多彩环球旅程游戏。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_97fc301222e46ab510c3380c', 'en', 'Atlas Bird', 'Take flight on a colorful journey around the world with Atlas Bird! Guide a cheerful little bird through challenging obstacles as it travels from one destination to the next.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_9d54047fe28d6938850490a3', 'zh-CN', '衡量日常物品的碳成本：AI 提示词、牛肉、航班', '一个比较日常活动与消费碳排放影响的工具，帮助人们聚焦真正有效的减排方向', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_9d54047fe28d6938850490a3', 'en', 'Measure the carbon cost of everyday items: prompts, beef, flights', 'Often, we focus on the wrong things when trying to combat climate change such as plastic straws, paper towels and AI prompts. However, the impact of these things are negligible compared to meat, cars, clothes and new tech.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_c502dc928da320af9bc4e54a', 'zh-CN', 'Porvi', '根据城市、日期和旅行风格生成逐日地图行程，按开放时间与交通餐饮耗时排路线，可调整对比。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_c502dc928da320af9bc4e54a', 'en', 'Porvi', 'Porvi turns your city, dates and travel style into a day-by-day plan on a map. Tell it who you''re traveling with, your pace and what you love, and every route is built around that.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_b0326fcc4a3980a306812bf6', 'zh-CN', 'Tavora 周末旅行预订平台', '印度德里 NCR 周末出行预订平台，提供逐日行程与人均费用，并代订火车、巴士、住宿和出租车，付款前确认。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_b0326fcc4a3980a306812bf6', 'en', 'Tavora', 'Where you can actually go this weekend from Delhi NCR, what the whole trip costs per person, and a day-by-day plan.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_b8e2af40b122fd6ec2d0b7a9', 'zh-CN', '自驾出行油费与路费计算器', '一款计算自驾油费与公路旅行开销的计算器。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_b8e2af40b122fd6ec2d0b7a9', 'en', 'A calculator for gas costs and road trip expenses', 'A calculator for estimating gas costs and road trip expenses.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_80130fd50e45f57b05213fe5', 'zh-CN', 'Nonce：为 AI 代理提供最小权限的 Gmail 访问', '开源网关让 AI 代理以最小权限访问 Gmail、日历和 Drive；代理须先说明意图才能获得限时、范围有限的令牌，可疑请求会交由用户批准。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_80130fd50e45f57b05213fe5', 'en', 'Nonce – Open-source, least-privilege Gmail access for AI agents', 'Hi HN! We built nonce, an open-source tool that sits between personal AI agents (Muse, Grok, ChatGPT, Claude) and your personal data in Gmail, Calendar, Drive and more.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_0f192e2c36aad5212ea8e53a', 'zh-CN', '像名人一样旅行', '以名人风格旅行为主题，具体功能与形式未说明。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_0f192e2c36aad5212ea8e53a', 'en', 'Travel Like a Celebrity', 'A travel-themed project about traveling like a celebrity; specific features and format are unspecified.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_c72d16e254cca314cafb6421', 'zh-CN', 'PressZero：浏览器端图片压缩工具', '完全在浏览器运行的免费开源图片压缩器，可精确压到目标 KB、漂白证件签名，并裁剪生物识别护照/签证照片，无需上传服务器。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_c72d16e254cca314cafb6421', 'en', 'PressZero', 'Free, open-source image compressor that runs 100% in your browser. Hits exact target-KB limits (e.g. 50 KB) in under 80ms, bleaches document signatures to pure 255-white, and provides biometric passport/visa cropping with 0 server uploads.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_cc7d7a4c56e5126154ac6a4d', 'zh-CN', 'HeyGo：出租车、货运与救护车一站式应用', 'HeyGo 将出租车、货运和救护车服务整合在同一款应用中。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_cc7d7a4c56e5126154ac6a4d', 'en', 'HeyGo - Cabs, freight, and ambulances in a single app', 'HeyGo brings cabs, freight, and ambulance services together in one app.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_a67cd486df136a76e5c57e3e', 'zh-CN', 'Ollin – 一句话生成逐日行程的旅行规划器', '根据一句话需求生成逐日旅行计划的规划工具。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_a67cd486df136a76e5c57e3e', 'en', 'Ollin – Trip planner that builds a day-by-day plan from one sentence', 'A trip planner that builds a day-by-day plan from a single sentence.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_82862b99e0a2c26382d287b9', 'zh-CN', '互动式旅行路线规划器 - 开源', '一个开源的互动式旅行路线规划器，用于规划旅行路线。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_82862b99e0a2c26382d287b9', 'en', 'Interactive Travel Route Planner - Open Source', 'An open-source interactive travel route planner for planning trips and routes.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_9c6a8b6e74d834c7b548286d', 'zh-CN', 'Prevo – AI 语音面试官，助力签证、入籍、求职与路演准备', 'AI 语音面试官，用于模拟签证、入籍、求职和路演面试练习。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_9c6a8b6e74d834c7b548286d', 'en', 'Prevo – AI voice interviewer for visa, citizenship, job and pitch prep', 'An AI voice interviewer for practicing visa, citizenship, job and pitch interviews.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_69c1a9aea8faa108b2a4d763', 'zh-CN', 'Plux 旅行规划器：免费、无广告且开源', 'Plux 是一款免费、无广告的开源旅行规划工具。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_69c1a9aea8faa108b2a4d763', 'en', 'Plux trip planner: free, no adn, and open source', 'Plux is a free, ad-free, open-source trip planner.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0);
