INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_41dd2da608c423de5d23a406', 'zh-CN', 'SeasonMap：用气候数据可视化何时去哪里旅行', '用气候数据可视化展示何时去何地旅行。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_41dd2da608c423de5d23a406', 'en', 'SeasonMap – when to travel where? visualized with climate data', 'Visualizes climate data to show when and where to travel.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_38b5c4b07e5f2de3e206ca1a', 'zh-CN', 'CT RailTime：更便捷的 CTrail 出行方式', '面向 CTrail 的出行工具，旨在让铁路出行更便捷。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_38b5c4b07e5f2de3e206ca1a', 'en', 'CT RailTime, a better way to travel on CTrail', 'A travel tool for CTrail aimed at making rail trips easier.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_8a4c44e9e1cb696a3fa6fbf3', 'zh-CN', 'ICAO ePassport Inspector：iOS 本地 NFC 护照验证', 'iOS 端 ICAO 电子护照检查工具，利用 NFC 在设备本地完成护照验证。', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0),('prd_8a4c44e9e1cb696a3fa6fbf3', 'en', 'ICAO ePassport Inspector – on-device NFC passport verification (iOS)', 'An iOS app for on-device NFC verification of ICAO ePassports.', 'llm:travel-localize-v1', 'enr_6b6001a2d24be80345c6894b', 0);
